import json

tasks = []
expenses = []


def add_task(title):
    task = {"id": len(tasks) + 1, "title": title, "done": False}
    tasks.append(task)
    return task


def find_task(task_id):
    for task in tasks:
        if task["id"] == task_id:
            return task
    return None


def show_tasks():
    if not tasks:
        print("Задач нет")
        return
    for task in tasks:
        mark = "x" if task["done"] else " "
        print(f"{task['id']}. [{mark}] {task['title']}")


def handle(line):
    parts = line.split()
    if not parts:
        return True
    command = parts[0]
    if command == "quit":
        print("До встречи!")
        return False
    if command == "add":
        task = add_task(" ".join(parts[1:]))
        print(f"Добавлено: #{task['id']} {task['title']}")
    elif command == "list":
        show_tasks()
    elif command == "done":
        task = find_task(int(parts[1]))
        if task is None:
            print(f"Нет задачи #{parts[1]}")
        else:
            task["done"] = True
            print(f"Выполнено: #{task['id']}")
    else:
        print(f"Неизвестная команда: {command}")
    return True


def main():
    while True:
        try:
            line = input()
        except EOFError:
            break
        if not handle(line):
            break


main()

